+import React, { useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [editing, setEditing] = useState(false);
+    const [name, setName] = useState(device.display_name ?? '');
+    const [saving, setSaving] = useState(false);
+    const [error, setError] = useState<string>();
+
+    const cancel = (): void => {
+        setName(device.display_name ?? '');
+        setError(undefined);
+        setEditing(false);
+    };
+
+    const save = async (): Promise<void> => {
+        if (name === (device.display_name ?? '')) {
+            setEditing(false);
+            return;
+        }
+        setSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setEditing(false);
+        } catch (e) {
+            setError('Failed to set display name.');
+        } finally {
+            setSaving(false);
+        }
+    };
+
+    if (!editing) {
+        return <div data-testid='device-detail-heading-read'>
+            <Heading size='h3'>{ device.display_name ?? device.device_id }</Heading>
+            <AccessibleButton kind='link_inline' onClick={() => {
+                setName(device.display_name ?? '');
+                setEditing(true);
+            }} data-testid='device-detail-rename'>
+                { _t('Rename') }
+            </AccessibleButton>
+        </div>;
+    }
+
+    return <div data-testid='device-detail-heading-edit'>
+        <input
+            aria-label={_t('Session name')}
+            data-testid='device-detail-name-input'
+            maxLength={100}
+            value={name}
+            onChange={event => setName(event.target.value)}
+            disabled={saving}
+        />
+        <p>{ _t('Session names may be visible to people you communicate with.') }</p>
+        { error && <div role='alert' data-testid='device-detail-name-error'>{ error }</div> }
+        <AccessibleButton kind='primary' onClick={save} disabled={saving} data-testid='device-detail-name-save'>
+            { saving ? <><Spinner w={16} h={16} />{ _t('Saving') }</> : _t('Save') }
+        </AccessibleButton>
+        <AccessibleButton kind='secondary' onClick={cancel} disabled={saving} data-testid='device-detail-name-cancel'>
+            { _t('Cancel') }
+        </AccessibleButton>
+    </div>;
+};
+
+export default DeviceDetailHeading;
